import { Role } from '../../common/enums/role.enum';

export const AUTH_TOKEN_TYPE = {
  ACCESS: 'access',
  REFRESH: 'refresh',
  OTP: 'otp',
  /** Short-lived; only opens a Socket.IO connection, never a REST request. */
  SOCKET: 'socket',
} as const;

export const AUTH_ERROR_CODE = {
  ACCESS_TOKEN_EXPIRED: 'ACCESS_TOKEN_EXPIRED',
  INVALID_ACCESS_TOKEN: 'INVALID_ACCESS_TOKEN',
  AUTH_TOKEN_MISSING: 'AUTH_TOKEN_MISSING',
} as const;

export const OTP_TOKEN_PURPOSE = {
  EMAIL_VERIFICATION: 'email_verification',
  PASSWORD_RESET: 'password_reset',
  TWO_FACTOR_LOGIN: 'two_factor_login',
} as const;

export type AuthTokenType = (typeof AUTH_TOKEN_TYPE)[keyof typeof AUTH_TOKEN_TYPE];
export type AuthErrorCode = (typeof AUTH_ERROR_CODE)[keyof typeof AUTH_ERROR_CODE];
export type OtpTokenPurpose = (typeof OTP_TOKEN_PURPOSE)[keyof typeof OTP_TOKEN_PURPOSE];

export interface AuthTokenPayload {
  sub: string;
  email: string;
  role: Role;
  tokenType: AuthTokenType;
  otpPurpose?: OtpTokenPurpose;
  challengeId?: string;
  twoFactorVerified?: boolean;
}

export { otpTokenSecret } from './jwt-secrets';

