    }

    try {
      const payload = await this.jwtService.verifyAsync<AuthTokenPayload>(refreshToken, {
        secret: this.refreshSecret,
      });
      const user = await this.usersService.findById(payload.sub);

      if (payload.tokenType !== AUTH_TOKEN_TYPE.REFRESH || !payload.sessionId || !payload.jti || !user?.emailVerified) {
        throw new UnauthorizedException('Invalid refresh token');
      }
      const tokenHash = this.hashRefreshToken(refreshToken);
      if (!(await this.refreshTokens.findActive(payload.sessionId, user.id, tokenHash))) {
        throw new UnauthorizedException('Invalid refresh token');
      }

      const twoFactorEnabled = await this.twoFactorService.isEnabled(user.id);

      if (twoFactorEnabled && payload.twoFactorVerified !== true) {
        throw new UnauthorizedException('Invalid refresh token');
      }

      return {
        user: UserResponseDto.fromUser({ ...user, twoFactorEnabled }),
        ...(await this.signTokens(user, payload.twoFactorVerified === true, {
          sessionId: payload.sessionId,
          tokenHash,
        })),
      };
    } catch (error) {
      if (
        error instanceof UnauthorizedException ||
        (error instanceof Error && ['TokenExpiredError', 'JsonWebTokenError', 'NotBeforeError'].includes(error.name))
      )
        throw new UnauthorizedException('Invalid refresh token');
      throw error;
    }
  }

  async logout(refreshToken: string) {
    try {
      const payload = await this.jwtService.verifyAsync<AuthTokenPayload>(refreshToken, { secret: this.refreshSecret });
      if (payload.tokenType !== AUTH_TOKEN_TYPE.REFRESH || !payload.sessionId || !payload.jti) {
        throw new UnauthorizedException('Invalid refresh token');
      }
      await this.refreshTokens.revoke(payload.sessionId, payload.sub);
      return { loggedOut: true };
    } catch (error) {
      if (
        error instanceof UnauthorizedException ||
        (error instanceof Error && ['TokenExpiredError', 'JsonWebTokenError', 'NotBeforeError'].includes(error.name))
      )
        throw new UnauthorizedException('Invalid refresh token');
      throw error;
    }
  }

  private hashRefreshToken(token: string) {
    return createHash('sha256').update(token).digest('hex');
  }

  async me(userId: string) {
    const user = await this.usersService.getById(userId);

    return UserResponseDto.fromUser({
      ...user,
      twoFactorEnabled: await this.twoFactorService.isEnabled(user.id),
    });
  }

  async verifyTwoFactorLogin(userId: string, challengeId: string | undefined, code: string) {
    const user = await this.usersService.findByIdWithPassword(userId);
    if (!user?.emailVerified) throw new UnauthorizedException('Invalid account');
    await this.twoFactorService.verifyLoginChallenge(userId, challengeId, code);

    return this.createLoginResponse(user, true);
  }

  async resendEmailVerificationOtp(email: string) {
    const user = await this.usersService.findByEmail(email);

    if (!user) {
      throw new BadRequestException('Unable to send verification email');
    }

    if (user.emailVerified) {
      return {
        emailVerified: true,
        expiresInMinutes: 0,
      };
    }

    await this.issueEmailVerificationOtp(user);

    return {
      emailVerified: false,
      expiresInMinutes: otpTtlMinutes(),
      otpToken: await this.signOtpToken(user, OTP_TOKEN_PURPOSE.EMAIL_VERIFICATION, otpTtlMinutes()),
    };
  }

  async verifyEmailOtp(userId: string, otp: string) {
    const user = await this.usersService.findById(userId);

    if (!user) {
      throw new BadRequestException('Invalid or expired verification code');
    }

    if (user.emailVerified) {
      throw new BadRequestException('Email is already verified');
    }

    const otpRecord = await this.emailOtpRepository.findLatestActiveByUserId(user.id);

    if (!otpRecord || otpRecord.attempts >= otpMaxAttempts()) {
      throw new BadRequestException('Invalid or expired verification code');
    }

    const otpMatches = await bcrypt.compare(otp, otpRecord.codeHash);

    if (!otpMatches) {
      await this.emailOtpRepository.recordFailedAttempt(otpRecord.id, user.id, otpMaxAttempts());

      throw new BadRequestException('Invalid or expired verification code');
    }

    const completed = await this.emailOtpRepository.complete(otpRecord.id, user.id, otpMaxAttempts());
    if (!completed) throw new BadRequestException('Invalid or expired verification code');
    const verifiedUser = await this.usersService.getById(user.id);
    return this.createAuthenticatedResponse(verifiedUser);
  }

  async forgotPassword(email: string) {
    const user = await this.usersService.findByEmail(email);
    if (user) {
      try {
        await this.issuePasswordResetOtp(user);
      } catch (error) {
        // A resend limit must not reveal whether this email belongs to an account.
        if (!(error instanceof HttpException) || error.getStatus() !== 429) throw error;
      }
    }

    return {
      expiresInMinutes: otpTtlMinutes(),
      otpToken: await this.signOtpToken(
        {
          id: user?.id ?? randomUUID(),
          email,
          // Unknown emails get a decoy token so the response never reveals whether an account exists.
          role: user?.role ?? Role.INSTRUCTOR,
        },
        OTP_TOKEN_PURPOSE.PASSWORD_RESET,
        otpTtlMinutes(),
      ),
    };
  }

  async resetPassword(userId: string, otp: string, password: string) {
    const user = await this.usersService.findById(userId);

    if (!user) {
      throw new BadRequestException('Invalid or expired password reset code');
    }

    const otpRecord = await this.passwordResetOtpRepository.findLatestActiveByUserId(user.id);

    if (!otpRecord || otpRecord.attempts >= otpMaxAttempts()) {
      throw new BadRequestException('Invalid or expired password reset code');
    }

    const otpMatches = await bcrypt.compare(otp, otpRecord.codeHash);

    if (!otpMatches) {
      await this.passwordResetOtpRepository.recordFailedAttempt(otpRecord.id, user.id, otpMaxAttempts());

      throw new BadRequestException('Invalid or expired password reset code');
    }

    const hashedPassword = await bcrypt.hash(password, 10);

    const completed = await this.passwordResetOtpRepository.complete(
      otpRecord.id,
      user.id,
      otpMaxAttempts(),
      hashedPassword,
    );
    if (!completed) throw new BadRequestException('Invalid or expired password reset code');

    return {
      passwordReset: true,
    };
  }

  private async issueEmailVerificationOtp(
    user: { id: string; email: string; emailVerified?: boolean | null },
    signup?: { password: string; role: Role },
  ) {
    if (user.emailVerified) {
      return;
    }

    const otp = generateOtp();
    const codeHash = await bcrypt.hash(otp, 10);
    const expiresAt = new Date(Date.now() + otpTtlMinutes() * 60 * 1000);

    await this.emailOtpRepository.create({
      userId: user.id,
      codeHash,
      expiresAt,
      signup,
    });
    await this.mailService.sendEmailVerificationOtp(user.email, otp);
  }

  private async issuePasswordResetOtp(user: { id: string; email: string }) {
    const otp = generateOtp();
    const codeHash = await bcrypt.hash(otp, 10);
    const expiresAt = new Date(Date.now() + otpTtlMinutes() * 60 * 1000);

    await this.passwordResetOtpRepository.create({
      userId: user.id,
      codeHash,
      expiresAt,
    });
    await this.mailService.sendPasswordResetOtp(user.email, otp);
  }

  private async signTokens(
    user: { id: string; email: string; role: Role; password?: string | null },
    twoFactorVerified = false,
    previous?: { sessionId: string; tokenHash: string },
  ) {
    const sessionId = previous?.sessionId ?? randomUUID();
    const payload = {
      sub: user.id,
      email: user.email,
      role: user.role,
      twoFactorVerified,
    };

    const [accessToken, refreshToken] = await Promise.all([
      this.jwtService.signAsync({
        ...payload,
        tokenType: AUTH_TOKEN_TYPE.ACCESS,
      } satisfies AuthTokenPayload),
      this.jwtService.signAsync(
        {
          ...payload,
          tokenType: AUTH_TOKEN_TYPE.REFRESH,
          sessionId,
          jti: randomUUID(),
        } satisfies AuthTokenPayload,
        {
          secret: this.refreshSecret,
          expiresIn: (process.env.JWT_REFRESH_EXPIRES_IN ?? '7d') as JwtSignOptions['expiresIn'],
        },
      ),
    ]);

    const accessTokenExpiry = this.getTokenExpiry(accessToken);
    const refreshTokenExpiry = this.getTokenExpiry(refreshToken);
    const saved = await this.refreshTokens.save(
      sessionId,
      user.id,
      this.hashRefreshToken(refreshToken),
      new Date(refreshTokenExpiry.expiresAt),
      previous?.tokenHash,
      user.password,
    );
    if (!saved) throw new UnauthorizedException('Invalid refresh token');

    return {
      accessToken,
      refreshToken,
      accessTokenExpiresAt: accessTokenExpiry.expiresAt,
      accessTokenExpiresInSeconds: accessTokenExpiry.expiresInSeconds,
      refreshTokenExpiresAt: refreshTokenExpiry.expiresAt,
      refreshTokenExpiresInSeconds: refreshTokenExpiry.expiresInSeconds,
    };
  }

  private getTokenExpiry(token: string) {
    const payload = this.jwtService.decode<DecodedTokenExpiry>(token);

    if (!payload?.exp) {
      throw new Error('Signed token is missing its expiration claim');
    }

    return {
      expiresAt: new Date(payload.exp * 1000).toISOString(),
      expiresInSeconds: Math.max(0, payload.exp - Math.floor(Date.now() / 1000)),
    };
  }

  private async createAuthenticatedResponse(user: {
    id: string;
    email: string;
    role: Role;
    password?: string | null;
  }): Promise<AuthenticatedResponse | TwoFactorChallengeResponse> {
    if (await this.twoFactorService.isEnabled(user.id)) {
      const challenge = await this.twoFactorService.createLoginChallenge(user.id, user.password);

      return {
        twoFactorRequired: true,
        twoFactorToken: await this.signOtpToken(
          user,
          OTP_TOKEN_PURPOSE.TWO_FACTOR_LOGIN,
          challenge.expiresInMinutes,
          challenge.challengeId,
        ),
        expiresInMinutes: challenge.expiresInMinutes,
      };
    }

    return this.createLoginResponse(user);
  }

  private async createLoginResponse(
    user: { id: string; email: string; role: Role; password?: string | null },
    twoFactorVerified = false,
  ) {
    const tokens = await this.signTokens(user, twoFactorVerified);
    const updatedUser = await this.usersService.recordLogin(user.id);
    return {
      user: UserResponseDto.fromUser({
        ...updatedUser,
        twoFactorEnabled: await this.twoFactorService.isEnabled(user.id),
      }),
      ...tokens,
    };
  }

  private async createEmailVerificationResponse(user: {
    id: string;
    email: string;
    role: Role;
    emailVerified?: boolean;
  }) {
    return {
      user: UserResponseDto.fromUser({
        ...user,
        role: user.role,
      }),
      otpToken: await this.signOtpToken(user, OTP_TOKEN_PURPOSE.EMAIL_VERIFICATION, otpTtlMinutes()),
      expiresInMinutes: otpTtlMinutes(),
    };
  }

  private signOtpToken(
    user: { id: string; email: string; role: Role },
    otpPurpose: OtpTokenPurpose,
    expiresInMinutes: number,
    challengeId?: string,
  ) {
    return this.jwtService.signAsync(
      {
        sub: user.id,
        email: user.email,
        role: user.role,
        tokenType: AUTH_TOKEN_TYPE.OTP,
        otpPurpose,
        challengeId,
      } satisfies AuthTokenPayload,
      {
        secret: otpTokenSecret(),
        expiresIn: expiresInMinutes * 60,
      },
    );
  }
}

