@ApiTags('Auth')
@ApiBearerAuth()
@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  @Post('login')
  @Public()
  @swagger.login()
  @ResponseMessage('User logged in successfully')
  @HttpCode(HttpStatus.OK)
  login(@Body() loginDto: LoginDto) {
    return this.authService.login(loginDto);
  }

  @Post('oauth/google')
  @Public()
  @swagger.googleLogin()
  @ResponseMessage('User logged in with Google successfully')
  @HttpCode(HttpStatus.OK)
  googleLogin(@Body() dto: GoogleLoginDto) {
    return this.authService.loginWithGoogle(dto.credential, dto.role);
  }

  @Post('register')
  @Public()
  @swagger.register()
  @ResponseMessage('User registered successfully and verification code sent')
  register(@Body() registerDto: RegisterDto) {
    return this.authService.register(registerDto);
  }

