  @Public()
  @swagger.refresh()
  @ResponseMessage('Tokens refreshed successfully')
  @HttpCode(HttpStatus.OK)
  refresh(@Body() refreshTokenDto: RefreshTokenDto) {
    return this.authService.refresh(refreshTokenDto.refreshToken);
  }

