  @Public()
  @swagger.resendEmailOtp()
  @ResponseMessage('Verification code sent successfully')
  @HttpCode(HttpStatus.OK)
  resendEmailOtp(@Body() dto: ResendEmailOtpDto) {
    return this.authService.resendEmailVerificationOtp(dto.email);
  }

