  @OtpTokenOnly(OTP_TOKEN_PURPOSE.EMAIL_VERIFICATION)
  @UseGuards(OtpAuthGuard)
  @swagger.verifyEmailOtp()
  @ResponseMessage('Email verified successfully')
  @HttpCode(HttpStatus.OK)
  verifyEmailOtp(@CurrentUser('id') userId: string, @Body() dto: VerifyEmailOtpDto) {
    return this.authService.verifyEmailOtp(userId, dto.otp);
  }

  @Post('password/forgot')
  @Public()
  @swagger.forgotPassword()
  @ResponseMessage('Password reset code sent successfully')
  @HttpCode(HttpStatus.OK)
  forgotPassword(@Body() dto: ForgotPasswordDto) {
    return this.authService.forgotPassword(dto.email);
  }

  @Post('password/reset')
  @OtpTokenOnly(OTP_TOKEN_PURPOSE.PASSWORD_RESET)
  @UseGuards(OtpAuthGuard)
  @swagger.resetPassword()
  @ResponseMessage('Password reset successfully')
  @HttpCode(HttpStatus.OK)
  resetPassword(@CurrentUser('id') userId: string, @Body() dto: ResetPasswordDto) {
    return this.authService.resetPassword(userId, dto.otp, dto.password);
  }

  @Post('2fa/verify')
  @OtpTokenOnly(OTP_TOKEN_PURPOSE.TWO_FACTOR_LOGIN)
  @UseGuards(OtpAuthGuard)
  @swagger.verifyTwoFactor()
  @ResponseMessage('Two-factor authentication verified successfully')
  @HttpCode(HttpStatus.OK)
  verifyTwoFactor(
    @CurrentUser('id') userId: string,
    @CurrentUser('challengeId') challengeId: string | undefined,
    @Body() dto: VerifyTwoFactorDto,
  ) {
    return this.authService.verifyTwoFactorLogin(userId, challengeId, dto.code);
  }

  @Get('me')
  @swagger.me()
  @ResponseMessage('Authenticated user fetched successfully')
  me(@CurrentUser('id') userId: string) {
    return this.authService.me(userId);
  }
}

