@Injectable()
export class TwoFactorRepository {
  constructor(private readonly prisma: PrismaService) {}

  findByUserId(userId: string): Promise<TwoFactorAuthentication | null> {
    return this.prisma.twoFactorAuthentication.findUnique({ where: { userId } });
  }

  async replacePendingSecret(
    userId: string,
    secretEncrypted: string,
  ): Promise<TwoFactorAuthentication | null> {
    const updated = await this.prisma.twoFactorAuthentication.updateMany({
      where: { userId, enabledAt: null },
      data: {
        secretEncrypted,
        recoveryCodeHashes: [],
        lastUsedStep: null,
      },
    });

    if (updated.count > 0) {
      return this.findByUserId(userId);
    }

    try {
      return await this.prisma.twoFactorAuthentication.create({
        data: { userId, secretEncrypted },
      });
    } catch (error) {
      if (!(error instanceof Prisma.PrismaClientKnownRequestError) || error.code !== 'P2002') {
        throw error;
      }

      const concurrentUpdate = await this.prisma.twoFactorAuthentication.updateMany({
        where: { userId, enabledAt: null },
        data: {
          secretEncrypted,
          recoveryCodeHashes: [],
          lastUsedStep: null,
        },
      });

      return concurrentUpdate.count > 0 ? this.findByUserId(userId) : null;
    }
  }

  async enable(
    userId: string,
    step: number,
    recoveryCodeHashes: string[],
    secretEncrypted: string,
  ): Promise<boolean> {
    const result = await this.prisma.twoFactorAuthentication.updateMany({
      where: { userId, enabledAt: null, secretEncrypted },
      data: {
        enabledAt: new Date(),
        lastUsedStep: step,
        recoveryCodeHashes,
      },
    });

    return result.count === 1;
  }

  async createChallenge(userId: string, expiresAt: Date): Promise<TwoFactorChallenge> {
    return this.prisma.$transaction(async (transaction) => {
      await transaction.twoFactorChallenge.deleteMany({ where: { userId } });

      return transaction.twoFactorChallenge.create({
        data: { userId, expiresAt },
      });
    });
  }

  findLatestUnexpiredChallenge(userId: string): Promise<TwoFactorChallenge | null> {
    return this.prisma.twoFactorChallenge.findFirst({
      where: {
        userId,
        expiresAt: { gt: new Date() },
      },
      orderBy: { createdAt: 'desc' },
    });
  }

  findActiveChallenge(id: string, userId: string): Promise<TwoFactorChallenge | null> {
    return this.prisma.twoFactorChallenge.findFirst({
      where: {
        id,
        userId,
        consumedAt: null,
        expiresAt: { gt: new Date() },
      },
    });
  }

  recordFailedChallenge(id: string, consume: boolean, lockExpiresAt?: Date) {
    return this.prisma.twoFactorChallenge.updateMany({
      where: { id, consumedAt: null },
      data: {
        attempts: { increment: 1 },
        consumedAt: consume ? new Date() : undefined,
